-- FINAL_30. Server-authoritative shared terminal, distributed fragments and owner recovery controls.

create or replace function public._bunker_v2_final_label(p_key text)
returns text language sql immutable security definer set search_path='' as $$
 select case p_key when 'coordinates' then 'Координаты' when 'sector' then 'Сектор' when 'access_code' then 'Код доступа' when 'gate_time' then 'Время открытия ворот' when 'password' then 'Пароль' else 'Параметр' end;
$$;
revoke all on function public._bunker_v2_final_label(text) from public,anon,authenticated;

create or replace function public._bunker_v2_final_normalize(p_key text,p_value text)
returns text language plpgsql immutable security definer set search_path='' as $$
declare v text:=upper(coalesce(p_value,''));begin
 if p_key='coordinates' then return regexp_replace(v,'[^0-9/]+','','g');
 elsif p_key in ('sector','access_code') then return regexp_replace(v,'[^0-9]+','','g');
 elsif p_key='gate_time' then return regexp_replace(v,'[^0-9:]+','','g');
 elsif p_key='password' then return regexp_replace(v,'[^A-Z0-9]+','','g');
 end if;return btrim(v);end;$$;
revoke all on function public._bunker_v2_final_normalize(text,text) from public,anon,authenticated;

create or replace function public._bunker_v2_final_part(p_key text,p_value text,p_part integer,p_total integer)
returns text language plpgsql immutable security definer set search_path='' as $$
declare v text:=p_value;begin
 if p_total<=1 then return v;end if;
 if p_key='coordinates' and p_total=2 then return btrim(split_part(v,'/',p_part));end if;
 if p_key='access_code' and p_total=2 then return case p_part when 1 then substring(v from 1 for 2) else substring(v from 3 for 2) end;end if;
 return case p_part when 1 then substring(v from 1 for greatest(1,ceil(char_length(v)/p_total::numeric)::integer)) else substring(v from greatest(1,ceil(char_length(v)/p_total::numeric)::integer)+1) end;
end;$$;
revoke all on function public._bunker_v2_final_part(text,text,integer,integer) from public,anon,authenticated;

create or replace function public._bunker_v2_final_hint(p_remaining integer,p_owner_level integer)
returns jsonb language plpgsql immutable security definer set search_path='' as $$
declare v_level integer:=greatest(coalesce(p_owner_level,0),case when p_remaining<=30 then 3 when p_remaining<=120 then 2 when p_remaining<=300 then 1 else 0 end);begin
 return jsonb_build_object('level',v_level,'text',case v_level when 1 then 'Соберите данные всех вагонов. Два параметра уже встречались в досье BK-17.' when 2 then 'Сверьте сектор и код доступа с BK-17. Координаты и код могут быть разделены на две части — соединяйте их по порядку.' when 3 then 'Проверьте формат: координаты вводятся через «/», время — ЧЧ:ММ, пароль — латиницей без пробелов.' else '' end);
end;$$;
revoke all on function public._bunker_v2_final_hint(integer,integer) from public,anon,authenticated;

create or replace function public._bunker_v2_final_transition()
returns trigger language plpgsql security definer set search_path='' as $$
declare v_contract integer;v_instance public.bunker_mission_instances%rowtype;v_bonus integer:=0;v_trade_bonus integer:=0;v_protocol_bonus integer:=0;v_now timestamptz:=clock_timestamp();begin
 if new.run_nonce is null or old.global_game_state is not distinct from new.global_game_state then return new;end if;
 select r.contract_version into v_contract from public.bunker_game_runs r where r.event_id=new.event_id and r.run_nonce=new.run_nonce;if v_contract is distinct from 2 then return new;end if;
 if new.global_game_state='FINAL_30' then
  select i.* into v_instance from public.bunker_mission_instances i where i.event_id=new.event_id and i.run_nonce=new.run_nonce and i.mission_code='FINAL_30' limit 1 for update;
  select coalesce(sum(greatest(-120,least(180,w.route_bonus-w.track_damage-(w.power_instability*30)))),0)::integer into v_bonus from public.bunker_wagon_state w where w.event_id=new.event_id and w.run_nonce=new.run_nonce;
  select least(120,count(*)::integer*30) into v_trade_bonus from public.bunker_inventory_transfers t where t.event_id=new.event_id and t.run_nonce=new.run_nonce and t.status='accepted';
  select case when exists(select 1 from public.bunker_mission_instances i where i.event_id=new.event_id and i.run_nonce=new.run_nonce and i.mission_code='MISSION_06' and i.outcome->>'status'='success') then 120 else 0 end into v_protocol_bonus;
  v_bonus:=greatest(-300,least(600,v_bonus+coalesce(v_trade_bonus,0)+v_protocol_bonus));
  update public.bunker_state set final_duration=1800+v_bonus,final_started_at=coalesce(final_started_at,v_now),updated_at=now() where event_id=new.event_id;
  update public.bunker_mission_instances set status='active',started_at=coalesce(started_at,v_now),deadline_at=v_now+make_interval(secs=>1800+v_bonus),definition=definition||jsonb_build_object('title','30 минут до Бункера','timeAdjustmentSeconds',v_bonus,'ownerHintLevel',0) where id=v_instance.id;
 end if;return new;end;$$;
revoke all on function public._bunker_v2_final_transition() from public,anon,authenticated;
drop trigger if exists bunker_v2_final_transition on public.bunker_state;create trigger bunker_v2_final_transition after update of global_game_state on public.bunker_state for each row execute function public._bunker_v2_final_transition();

create or replace function public._submit_bunker_command_final(p_event_slug text,p_device_key text,p_command_id uuid,p_command_type text,p_payload jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare v_event_id uuid;v_guest public.guests%rowtype;v_state public.bunker_state%rowtype;v_run public.bunker_game_runs%rowtype;v_instance public.bunker_mission_instances%rowtype;v_existing public.bunker_command_receipts%rowtype;v_hash text;v_parameter public.bunker_final_parameters%rowtype;v_input text;v_correct integer:=0;v_total integer:=0;v_success boolean:=false;v_attempt integer;v_result jsonb;v_now timestamptz:=clock_timestamp();begin
 if p_command_id is null or p_command_type<>'request_access' or p_payload is null or jsonb_typeof(p_payload)<>'object' or (select count(*) from jsonb_object_keys(p_payload))<>5 or not (p_payload ?& array['coordinates','sector','accessCode','gateTime','password']) then raise exception 'invalid final access request' using errcode='22023';end if;
 select e.id into v_event_id from public.events e where e.slug=public._normalize_spaces(p_event_slug);if v_event_id is null then raise exception 'Bunker event not found' using errcode='P0002';end if;
 select g.* into v_guest from public.guests g where g.event_id=v_event_id and g.id=public._bunker_guest_id(p_event_slug,p_device_key);if v_guest.id is null then raise exception 'registered Bunker guest required' using errcode='42501';end if;
 select s.* into v_state from public.bunker_state s where s.event_id=v_event_id for update;if v_state.run_nonce is null or v_state.global_game_state<>'FINAL_30' then raise exception 'final terminal is not active' using errcode='55000';end if;
 select r.* into v_run from public.bunker_game_runs r where r.event_id=v_event_id and r.run_nonce=v_state.run_nonce;if v_run.contract_version<>2 then raise exception 'active Bunker V2 run required' using errcode='55000';end if;
 v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('commandType',p_command_type,'payload',p_payload)::text,'UTF8'),'sha256'),'hex');select r.* into v_existing from public.bunker_command_receipts r where r.run_nonce=v_state.run_nonce and r.actor_kind='guest' and r.actor_id=v_guest.id and r.command_id=p_command_id;if v_existing.id is not null then if v_existing.request_hash<>v_hash then raise exception 'idempotency_conflict' using errcode='55000';end if;return v_existing.result;end if;
 select i.* into v_instance from public.bunker_mission_instances i where i.event_id=v_event_id and i.run_nonce=v_state.run_nonce and i.mission_code='FINAL_30' limit 1 for update;if v_instance.id is null or v_instance.status<>'active' then raise exception 'final instance unavailable' using errcode='55000';end if;
 perform 1 from public.bunker_final_parameters p where p.event_id=v_event_id and p.run_nonce=v_state.run_nonce order by p.parameter_key for update;
 for v_parameter in select p.* from public.bunker_final_parameters p where p.event_id=v_event_id and p.run_nonce=v_state.run_nonce order by p.parameter_key loop
  v_total:=v_total+1;v_input:=case v_parameter.parameter_key when 'coordinates' then p_payload->>'coordinates' when 'sector' then p_payload->>'sector' when 'access_code' then p_payload->>'accessCode' when 'gate_time' then p_payload->>'gateTime' when 'password' then p_payload->>'password' end;
  if public._bunker_v2_final_normalize(v_parameter.parameter_key,v_input)=v_parameter.normalized_value then
   v_correct:=v_correct+1;update public.bunker_final_parameters set status='resolved',source_kind=coalesce(source_kind,'final_terminal'),source_instance_id=coalesce(source_instance_id,v_instance.id),resolved_at=coalesce(resolved_at,v_now) where id=v_parameter.id;
  end if;
 end loop;
 v_success:=v_correct=v_total;
 select count(*)::integer+1 into v_attempt from public.bunker_mission_decisions d where d.instance_id=v_instance.id and d.decision_key like 'final_access_%';
 insert into public.bunker_mission_decisions(event_id,run_nonce,instance_id,decision_key,actor_kind,actor_id,actor_scope_key,status,instance_version,command_id,payload,outcome,confirmed_at) values(v_event_id,v_state.run_nonce,v_instance.id,'final_access_'||v_attempt,'guest',v_guest.id,v_guest.id::text,'confirmed',v_instance.instance_version,p_command_id,jsonb_build_object('submitted',true),jsonb_build_object('correctCount',v_correct,'total',v_total,'success',v_success),v_now);
 if v_success then
  update public.bunker_mission_instances set status='completed',completed_at=v_now,outcome=jsonb_build_object('status','success','attempts',v_attempt,'finishTimeSeconds',greatest(0,extract(epoch from(v_now-coalesce(started_at,v_now)))::integer)) where id=v_instance.id;
  update public.bunker_state set bunker_revealed=true,global_game_state='BUNKER_OPEN',updated_at=now() where event_id=v_event_id;
 end if;
 v_result:=jsonb_build_object('contractVersion',2,'status','accepted','commandId',p_command_id,'commandType','request_access');insert into public.bunker_command_receipts(event_id,run_nonce,actor_kind,actor_id,command_id,command_type,request_hash,result) values(v_event_id,v_state.run_nonce,'guest',v_guest.id,p_command_id,'request_access',v_hash,v_result);insert into public.bunker_game_events(event_id,run_nonce,carriage_id,guest_id,event_type,actor_type,actor_id,command_id,correlation_id,instance_id,schema_version,payload) values(v_event_id,v_state.run_nonce,v_guest.carriage_id,v_guest.id,case when v_success then 'final_access_granted' else 'final_access_checked' end,'guest',v_guest.id,p_command_id,p_command_id,v_instance.id,2,jsonb_build_object('correctCount',v_correct,'total',v_total,'attempt',v_attempt));return v_result;
end;$$;
revoke all on function public._submit_bunker_command_final(text,text,uuid,text,jsonb) from public,anon,authenticated;

create or replace function public.submit_bunker_command(p_event_slug text,p_device_key text,p_command_id uuid,p_command_type text,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_event_id uuid;v_guest_id uuid;v_state public.bunker_state%rowtype;v_existing public.bunker_command_receipts%rowtype;v_hash text;v_instance_id uuid;begin select e.id into v_event_id from public.events e where e.slug=public._normalize_spaces(p_event_slug);if v_event_id is null then raise exception 'Bunker event not found' using errcode='P0002';end if;v_guest_id:=public._bunker_guest_id(p_event_slug,p_device_key);if v_guest_id is null then raise exception 'registered Bunker guest required' using errcode='42501';end if;select s.* into v_state from public.bunker_state s where s.event_id=v_event_id for update;if v_state.run_nonce is null then raise exception 'active Bunker V2 run required' using errcode='55000';end if;v_hash:=encode(extensions.digest(convert_to(jsonb_build_object('commandType',p_command_type,'payload',p_payload)::text,'UTF8'),'sha256'),'hex');select r.* into v_existing from public.bunker_command_receipts r where r.run_nonce=v_state.run_nonce and r.actor_kind='guest' and r.actor_id=v_guest_id and r.command_id=p_command_id;if v_existing.id is not null then if v_existing.request_hash<>v_hash then raise exception 'idempotency_conflict' using errcode='55000';end if;return v_existing.result;end if;if v_state.global_game_state='MISSION_01' then begin v_instance_id:=(p_payload->>'instanceId')::uuid;exception when others then v_instance_id:=null;end;perform 1 from public.bunker_mission_instances i where i.id=v_instance_id for update;perform 1 from public.bunker_mission_members m where m.instance_id=v_instance_id order by m.id for update;return public._submit_bunker_command_m01(p_event_slug,p_device_key,p_command_id,p_command_type,p_payload);elsif v_state.global_game_state='MISSION_02' then return public._submit_bunker_command_m02(p_event_slug,p_device_key,p_command_id,p_command_type,p_payload);elsif v_state.global_game_state='MISSION_03' then return public._submit_bunker_command_m03(p_event_slug,p_device_key,p_command_id,p_command_type,p_payload);elsif v_state.global_game_state='MISSION_04' then return public._submit_bunker_command_m04(p_event_slug,p_device_key,p_command_id,p_command_type,p_payload);elsif v_state.global_game_state='MISSION_05' then return public._submit_bunker_command_m05(p_event_slug,p_device_key,p_command_id,p_command_type,p_payload);elsif v_state.global_game_state='MISSION_06' then return public._submit_bunker_command_m06(p_event_slug,p_device_key,p_command_id,p_command_type,p_payload);elsif v_state.global_game_state='FINAL_30' then return public._submit_bunker_command_final(p_event_slug,p_device_key,p_command_id,p_command_type,p_payload);end if;raise exception 'Bunker command unavailable at current stage' using errcode='55000';end;$$;
revoke all on function public.submit_bunker_command(text,text,uuid,text,jsonb) from public,anon,authenticated;grant execute on function public.submit_bunker_command(text,text,uuid,text,jsonb) to anon,authenticated;

create or replace function public._bunker_v2_final_progress(p_event_id uuid,p_run_nonce uuid)
returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('solved',(select count(*) from public.bunker_final_parameters p where p.event_id=p_event_id and p.run_nonce=p_run_nonce and p.status='resolved'),'total',(select count(*) from public.bunker_final_parameters p where p.event_id=p_event_id and p.run_nonce=p_run_nonce),'wrongAttempts',(select count(*) from public.bunker_mission_decisions d join public.bunker_mission_instances i on i.id=d.instance_id where i.event_id=p_event_id and i.run_nonce=p_run_nonce and i.mission_code='FINAL_30' and d.decision_key like 'final_access_%' and coalesce((d.outcome->>'success')::boolean,false)=false));$$;
revoke all on function public._bunker_v2_final_progress(uuid,uuid) from public,anon,authenticated;

create or replace function public.get_guest_bunker_v2_final(p_event_slug text,p_device_key text) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_event_id uuid;v_guest public.guests%rowtype;v_state public.bunker_state%rowtype;v_run public.bunker_game_runs%rowtype;v_instance public.bunker_mission_instances%rowtype;v_wagon public.carriages%rowtype;v_fragments jsonb;v_progress jsonb;v_remaining integer;v_hint jsonb;v_owner_level integer;v_now timestamptz:=clock_timestamp();begin select e.id into v_event_id from public.events e where e.slug=public._normalize_spaces(p_event_slug);if v_event_id is null then return jsonb_build_object('contractVersion',2,'status','not_found','serverNow',v_now);end if;select g.* into v_guest from public.guests g where g.event_id=v_event_id and g.id=public._bunker_guest_id(p_event_slug,p_device_key);if v_guest.id is null then return jsonb_build_object('contractVersion',2,'status','not_found','serverNow',v_now);end if;select s.* into v_state from public.bunker_state s where s.event_id=v_event_id;if v_state.run_nonce is null then return jsonb_build_object('contractVersion',2,'status','idle','serverNow',v_now);end if;select r.* into v_run from public.bunker_game_runs r where r.event_id=v_event_id and r.run_nonce=v_state.run_nonce;if v_run.contract_version<>2 then return jsonb_build_object('contractVersion',2,'status','legacy','serverNow',v_now);end if;if v_state.global_game_state not in ('FINAL_30','BUNKER_OPEN') then return jsonb_build_object('contractVersion',2,'status','idle','serverNow',v_now);end if;select i.* into v_instance from public.bunker_mission_instances i where i.event_id=v_event_id and i.run_nonce=v_state.run_nonce and i.mission_code='FINAL_30' limit 1;select c.* into v_wagon from public.carriages c where c.id=v_guest.carriage_id;select coalesce(jsonb_agg(jsonb_build_object('parameter',a.value->>'parameter','label',public._bunker_v2_final_label(a.value->>'parameter'),'part',(a.value->>'part')::integer,'totalParts',(a.value->>'totalParts')::integer,'value',public._bunker_v2_final_part(p.parameter_key,p.canonical_value,(a.value->>'part')::integer,(a.value->>'totalParts')::integer)) order by a.ordinal),'[]'::jsonb) into v_fragments from jsonb_array_elements(v_instance.definition->'parameterDistribution') with ordinality a(value,ordinal) join public.bunker_final_parameters p on p.event_id=v_event_id and p.run_nonce=v_state.run_nonce and p.parameter_key=a.value->>'parameter' where a.value->>'wagonId'=v_guest.carriage_id::text;v_progress:=public._bunker_v2_final_progress(v_event_id,v_state.run_nonce);v_remaining:=greatest(0,extract(epoch from(coalesce(v_instance.deadline_at,v_now)-v_now))::integer);v_owner_level:=coalesce((v_instance.definition->>'ownerHintLevel')::integer,0);v_hint:=public._bunker_v2_final_hint(v_remaining,v_owner_level);return jsonb_build_object('contractVersion',2,'status',case when v_state.global_game_state='BUNKER_OPEN' then 'completed' else 'active' end,'serverNow',v_now,'deadlineAt',coalesce(v_instance.deadline_at,v_now),'title','30 минут до Бункера','instanceId',v_instance.id,'wagon',jsonb_build_object('number',v_wagon.number,'label',v_wagon.label),'fragments',v_fragments,'terminal',jsonb_build_object('solved',(v_progress->>'solved')::integer,'total',(v_progress->>'total')::integer,'wrongAttempts',(v_progress->>'wrongAttempts')::integer,'unlocked',v_state.global_game_state='BUNKER_OPEN'),'hint',v_hint,'timeAdjustmentSeconds',coalesce((v_instance.definition->>'timeAdjustmentSeconds')::integer,0));end;$$;
revoke all on function public.get_guest_bunker_v2_final(text,text) from public,anon,authenticated;grant execute on function public.get_guest_bunker_v2_final(text,text) to anon,authenticated;

create or replace function public.get_bunker_v2_final_screen(p_event_slug text) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_event_id uuid;v_state public.bunker_state%rowtype;v_instance public.bunker_mission_instances%rowtype;v_progress jsonb;v_remaining integer;v_hint jsonb;v_now timestamptz:=clock_timestamp();begin select e.id into v_event_id from public.events e where e.slug=public._normalize_spaces(p_event_slug);if v_event_id is null then return jsonb_build_object('contractVersion',2,'status','not_found','serverNow',v_now);end if;select s.* into v_state from public.bunker_state s where s.event_id=v_event_id;if v_state.run_nonce is null then return jsonb_build_object('contractVersion',2,'status','idle','serverNow',v_now);end if;if v_state.global_game_state not in ('FINAL_30','BUNKER_OPEN') then return jsonb_build_object('contractVersion',2,'status','idle','serverNow',v_now);end if;select i.* into v_instance from public.bunker_mission_instances i where i.event_id=v_event_id and i.run_nonce=v_state.run_nonce and i.mission_code='FINAL_30' limit 1;v_progress:=public._bunker_v2_final_progress(v_event_id,v_state.run_nonce);v_remaining:=greatest(0,extract(epoch from(coalesce(v_instance.deadline_at,v_now)-v_now))::integer);v_hint:=public._bunker_v2_final_hint(v_remaining,coalesce((v_instance.definition->>'ownerHintLevel')::integer,0));return jsonb_build_object('contractVersion',2,'status',case when v_state.global_game_state='BUNKER_OPEN' then 'completed' else 'active' end,'serverNow',v_now,'deadlineAt',coalesce(v_instance.deadline_at,v_now),'solved',(v_progress->>'solved')::integer,'total',(v_progress->>'total')::integer,'wrongAttempts',(v_progress->>'wrongAttempts')::integer,'unlocked',v_state.global_game_state='BUNKER_OPEN','hintLevel',(v_hint->>'level')::integer,'timeAdjustmentSeconds',coalesce((v_instance.definition->>'timeAdjustmentSeconds')::integer,0));end;$$;
