create or replace function public.get_owner_bunker_v2_final(p_event_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_slug text;begin perform public._require_bunker_owner(p_event_id);select e.slug into v_slug from public.events e where e.id=p_event_id;return public.get_bunker_v2_final_screen(v_slug);end;$$;
