create or replace function public.owner_bunker_v2_add_final_time(p_event_id uuid,p_seconds integer) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_state public.bunker_state%rowtype;v_instance public.bunker_mission_instances%rowtype;v_seconds integer;begin perform public._require_bunker_owner(p_event_id);v_seconds:=coalesce(p_seconds,0);if v_seconds<1 or v_seconds>300 then raise exception 'final time increment must be 1..300 seconds' using errcode='22023';end if;select s.* into v_state from public.bunker_state s where s.event_id=p_event_id for update;if v_state.global_game_state<>'FINAL_30' then raise exception 'final is not active' using errcode='55000';end if;select i.* into v_instance from public.bunker_mission_instances i where i.event_id=p_event_id and i.run_nonce=v_state.run_nonce and i.mission_code='FINAL_30' limit 1 for update;v_seconds:=least(v_seconds,greatest(0,2400-v_state.final_duration));update public.bunker_state set final_duration=final_duration+v_seconds,updated_at=now() where event_id=p_event_id;update public.bunker_mission_instances set deadline_at=deadline_at+make_interval(secs=>v_seconds) where id=v_instance.id;return jsonb_build_object('status','updated','addedSeconds',v_seconds);end;$$;
revoke all on function public.owner_bunker_v2_add_final_time(uuid,integer) from public,anon,authenticated;grant execute on function public.owner_bunker_v2_add_final_time(uuid,integer) to authenticated;

create or replace function public.owner_bunker_v2_final_hint(p_event_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_state public.bunker_state%rowtype;v_instance public.bunker_mission_instances%rowtype;v_level integer;begin perform public._require_bunker_owner(p_event_id);select s.* into v_state from public.bunker_state s where s.event_id=p_event_id;if v_state.global_game_state<>'FINAL_30' then raise exception 'final is not active' using errcode='55000';end if;select i.* into v_instance from public.bunker_mission_instances i where i.event_id=p_event_id and i.run_nonce=v_state.run_nonce and i.mission_code='FINAL_30' limit 1 for update;v_level:=least(3,coalesce((v_instance.definition->>'ownerHintLevel')::integer,0)+1);update public.bunker_mission_instances set definition=jsonb_set(definition,'{ownerHintLevel}',to_jsonb(v_level),true) where id=v_instance.id;return jsonb_build_object('status','updated','hintLevel',v_level);end;$$;
revoke all on function public.owner_bunker_v2_final_hint(uuid) from public,anon,authenticated;grant execute on function public.owner_bunker_v2_final_hint(uuid) to authenticated;

create or replace function public.owner_bunker_v2_emergency_open(p_event_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$ declare v_state public.bunker_state%rowtype;v_instance public.bunker_mission_instances%rowtype;v_now timestamptz:=clock_timestamp();begin perform public._require_bunker_owner(p_event_id);select s.* into v_state from public.bunker_state s where s.event_id=p_event_id for update;if v_state.global_game_state<>'FINAL_30' then raise exception 'final is not active' using errcode='55000';end if;select i.* into v_instance from public.bunker_mission_instances i where i.event_id=p_event_id and i.run_nonce=v_state.run_nonce and i.mission_code='FINAL_30' limit 1 for update;update public.bunker_final_parameters set status='resolved',source_kind='owner_emergency',source_instance_id=v_instance.id,resolved_at=coalesce(resolved_at,v_now) where event_id=p_event_id and run_nonce=v_state.run_nonce;update public.bunker_mission_instances set status='completed',completed_at=v_now,outcome=jsonb_build_object('status','emergency_open','finishTimeSeconds',greatest(0,extract(epoch from(v_now-coalesce(started_at,v_now)))::integer)) where id=v_instance.id;update public.bunker_state set bunker_revealed=true,global_game_state='BUNKER_OPEN',updated_at=now() where event_id=p_event_id;return jsonb_build_object('status','opened','mode','emergency');end;$$;
revoke all on function public.owner_bunker_v2_emergency_open(uuid) from public,anon,authenticated;grant execute on function public.owner_bunker_v2_emergency_open(uuid) to authenticated;
